const i=new Intl.NumberFormat("en-US",{maximumFractionDigits:0}),a=new Intl.NumberFormat("en-US",{maximumFractionDigits:1,minimumFractionDigits:1});function m(t,e=1){const n=Math.abs(t);return n>=1e9?`${(t/1e9).toFixed(e)}B`:n>=1e6?`${(t/1e6).toFixed(e)}M`:n>=1e4?`${(t/1e3).toFixed(n>=1e5?0:e)}K`:i.format(t)}const s=t=>Number.isFinite(t)?i.format(Math.round(t)):"–",o=t=>Number.isFinite(t)?a.format(t):"–",r=(t,e=1)=>Number.isFinite(t)?`$${m(t,e)}`:"–",u=(t,e=1)=>Number.isFinite(t)?`${(t*100).toFixed(e)}%`:"–",c=(t,e=1)=>Number.isFinite(t)?`${t>=0?"+":"−"}${Math.abs(t*100).toFixed(e)}%`:"–",f=(t,e=1)=>Number.isFinite(t)?`${t>=0?"+":"−"}${Math.abs(t*100).toFixed(e)} pts`:"–";function F(t,e,n=1){return e==="usd"?r(t,n):m(t,n)}function b(t){const[e,n]=t.split("-").map(Number);return`${["Jan","Feb","Mar","Apr","May","Jun","Jul","Aug","Sep","Oct","Nov","Dec"][n-1]} ${e}`}export{c as a,r as b,u as c,s as d,f as e,F as f,m as g,o as h,b as m};
